impl<'tree> FromNodeKind<'tree> for AdmittedBaseContentItemChoice<'tree> {
    /** Classify a node into this choice's own alternatives.

    Returns `None` for a node of any other kind. That is a refusal,
    not a failure: the caller holds a node this choice does not
    describe, and saying so is the only true answer available.*/
    fn from_node(node: tree_sitter::Node<'tree>) -> Option<Self> {
        match node.kind() {
            "underline_begin" => Some(AdmittedBaseContentItemChoice::UnderlineBegin(
                UnderlineBeginNode(node),
            )),
            "underline_end" => Some(AdmittedBaseContentItemChoice::UnderlineEnd(
                UnderlineEndNode(node),
            )),
            "pause_token" => Some(AdmittedBaseContentItemChoice::PauseToken(PauseTokenNode(
                node,
            ))),
            "word_with_optional_annotations" => {
                Some(AdmittedBaseContentItemChoice::WordWithOptionalAnnotations(
                    WordWithOptionalAnnotationsNode(node),
                ))
            }
            "nonword_with_optional_annotations" => Some(
                AdmittedBaseContentItemChoice::NonwordWithOptionalAnnotations(
                    NonwordWithOptionalAnnotationsNode(node),
                ),
            ),
            "other_spoken_event" => Some(AdmittedBaseContentItemChoice::OtherSpokenEvent(
                OtherSpokenEventNode(node),
            )),
            "long_feature" => Some(AdmittedBaseContentItemChoice::LongFeature(LongFeatureNode(
                node,
            ))),
            "nonvocal" => Some(AdmittedBaseContentItemChoice::Nonvocal(NonvocalNode(node))),
            "freecode" => Some(AdmittedBaseContentItemChoice::Freecode(FreecodeNode(node))),
            "bullet" => Some(AdmittedBaseContentItemChoice::Bullet(BulletNode(node))),
            _ => None,
        }
    }
}
