impl<'tree, 'source> SourceBound<'tree, 'source, BirthplaceOfHeaderNode<'tree>> {
    /// Extract under the compiled grammar proof, preserving other recovery.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        SourceChildren<'tree, 'source, AdmittedBirthplaceOfHeaderChildren<'tree>>,
        ReconstructionFault,
    > {
        extract_birthplace_of_header_admitted(
            grammar
                .bind(self.source_slice())
                .map_err(ReconstructionFault::GrammarBinding)?,
        )
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct ERROR children under the same admitted producer contract.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_birthplace_of_header_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, AdmittedBirthplaceOfHeaderChildren<'tree>>>,
        ReconstructionFault,
    > {
        let parent = grammar
            .bind(self)
            .map_err(ReconstructionFault::GrammarBinding)?;
        if self.node.is_error() {
            extract_birthplace_of_header_admitted(parent).map(Some)
        } else {
            Ok(None)
        }
    }
}

