/// `comment_header`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_comment_header_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<CommentHeaderChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_comment_header(CommentHeaderNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

