pub fn extract_err_dependent_tier_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ErrDependentTierChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_err_dependent_tier(ErrDependentTierNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

