/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_gra_relation<'tree>(
    node: GraRelationNode<'tree>,
) -> Result<GraRelationChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        {
            let index = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_188, &cont_of(&SHAPES_37)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("gra_index") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(GraIndexNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(GraIndexNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_1 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_182, &cont_of(&SHAPES_38)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("pipe") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(PipeNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(PipeNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let head = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_184, &cont_of(&SHAPES_39)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("gra_head") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(GraHeadNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(GraHeadNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_3 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_182, &cont_of(&SHAPES_40)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("pipe") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(PipeNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(PipeNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let relation = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_186, &cont_of(&SHAPES_3)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("gra_relation_name") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(GraRelationNameNode(node))
                                        }
                                        SelectedNodePresence::Missing => NodeSlot::Missing(
                                            KindMissing(GraRelationNameNode(node)),
                                        ),
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            GraRelationChildren {
                index,
                child_1,
                head,
                child_3,
                relation,
                trailing_extras,
                unexpected,
            }
        }
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, GraRelationNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, GraRelationChildren<'tree>>, ReconstructionFault>
    {
        Ok(SourceChildren {
            children: extract_gra_relation(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_gra_relation_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, GraRelationChildren<'tree>>>,
        ReconstructionFault,
    > {
        extract_gra_relation_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `gra_relation`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_gra_relation_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<GraRelationChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_gra_relation(GraRelationNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

