/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_id_ses<'tree>(
    node: IdSesNode<'tree>,
) -> Result<IdSesChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_249, &cont_of(&SHAPES_3)) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        IdSesChoice::SesCombined(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("ses_combined") => {
                                                                            SesCombinedNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        IdSesChoice::SesCodeValue(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("ses_code_value") => {
                                                                            SesCodeValueNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                2usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        IdSesChoice::EthnicityValue(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("ethnicity_value") => {
                                                                            EthnicityValueNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                3usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        IdSesChoice::GenericIdSes(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("generic_id_ses") => {
                                                                            GenericIdSesNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        IdSesChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, IdSesNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, IdSesChildren<'tree>>, ReconstructionFault> {
        Ok(SourceChildren {
            children: extract_id_ses(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_id_ses_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, IdSesChildren<'tree>>>, ReconstructionFault>
    {
        extract_id_ses_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `id_ses`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_id_ses_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<IdSesChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_id_ses(IdSesNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

