pub struct LinkerChildren<'tree> {
    /// The rule's whole content, as a single position: the carrier
    /// convention (spec Section 5) mirroring `fold::slot_of`.
    pub content: Positioned<'tree, ClassifiedSlot<'tree, LinkerChoice<'tree>>>,
    /// Extras that trail the last child of this node (spec Section 5).
    pub trailing_extras: Vec<Extra<'tree>>,
    /// Children that filled no grammar position: the Unexpected sink
    /// (spec Section 7). Never dropped.
    pub unexpected: Vec<tree_sitter::Node<'tree>>,
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Classify this canonical node, retaining every recovery outcome.
    #[must_use]
    pub fn extract_linker(self) -> SourceChildren<'tree, 'source, LinkerChildren<'tree>> {
        SourceChildren {
            children: extract_linker(self.node),
            parent: self,
        }
    }
}
/// Classify this supertype node by its own kind (spec Section 7).
#[must_use]
pub fn extract_linker<'tree>(node: tree_sitter::Node<'tree>) -> LinkerChildren<'tree> {
    let __slot = if node.is_error() {
        NodeSlot::Error(node)
    } else if node.is_missing() {
        NodeSlot::Missing(node)
    } else {
        match LinkerChoice::from_node(node) {
            Some(__classified) => NodeSlot::Present(__classified),
            None => NodeSlot::Unexpected(node),
        }
    };
    LinkerChildren {
        content: Positioned::new(Vec::new(), __slot),
        trailing_extras: Vec::new(),
        unexpected: Vec::new(),
    }
}

