fn extract_long_feature_admitted<'tree, 'source>(
    parent: AdmittedParent<'tree, 'source>,
) -> Result<SourceChildren<'tree, 'source, AdmittedLongFeatureChildren<'tree>>, ReconstructionFault>
{
    let __raw = parent.source.node;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new_admitted(&__children, parent.grammar);
    Ok(SourceChildren {
        children: {
            let content = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_284, &cont_of(&SHAPES_3)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection
                            .consume_with(|__selected, __unexpected| {
                                let (leading_extras, selected) = __selected
                                    .composite_position(__unexpected)?;
                                let slot = match selected {
                                    SelectedComposite::Error(node) => NodeSlot::Error(node),
                                    SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                    SelectedComposite::Value(__selected) => {
                                        NodeSlot::Present(
                                            ({
                                                let MatchDecision::Choice { alternative, value } = __selected
                                                    .read()?
                                                    .decision else {
                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                };
                                                let __selected = __selected.child(value)?;
                                                match alternative {
                                                    0usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            AdmittedLongFeatureChoice::LongFeatureBegin(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        at,
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let node = __selected.node_at(at)?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("long_feature_begin") => {
                                                                                LongFeatureBeginNode(node)
                                                                            }
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    1usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            AdmittedLongFeatureChoice::LongFeatureEnd(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        at,
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let node = __selected.node_at(at)?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("long_feature_end") => {
                                                                                LongFeatureEndNode(node)
                                                                            }
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    _ => Err(ReconstructionFault::UnexpectedDecision),
                                                }
                                            })?,
                                        )
                                    }
                                };
                                Ok(Positioned::new(leading_extras, slot))
                            })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            AdmittedLongFeatureChildren {
                content,
                trailing_extras,
                unexpected,
            }
        },
        parent: parent.source,
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, LongFeatureNode<'tree>> {
    /// Extract under the compiled grammar proof, preserving other recovery.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        SourceChildren<'tree, 'source, AdmittedLongFeatureChildren<'tree>>,
        ReconstructionFault,
    > {
        extract_long_feature_admitted(
            grammar
                .bind(self.source_slice())
                .map_err(ReconstructionFault::GrammarBinding)?,
        )
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct ERROR children under the same admitted producer contract.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_long_feature_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, AdmittedLongFeatureChildren<'tree>>>,
        ReconstructionFault,
    > {
        let parent = grammar
            .bind(self)
            .map_err(ReconstructionFault::GrammarBinding)?;
        if self.node.is_error() {
            extract_long_feature_admitted(parent).map(Some)
        } else {
            Ok(None)
        }
    }
}

