/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_media_filename<'tree>(
    node: MediaFilenameNode<'tree>,
) -> Result<MediaFilenameChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_318, &cont_of(&SHAPES_3)) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        MediaFilenameChoice::DoubleQuote(
                                                            ({
                                                                let MatchDecision::Sequence(__members) = __selected
                                                                    .read()?
                                                                    .decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                if __members.len() != 3usize {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                }
                                                                let mut __members = __members.into_iter();
                                                                let child_0 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    {
                                                                        let (leading_extras, leaf) = __selected
                                                                            .leaf_position(__unexpected)?;
                                                                        let slot = match leaf {
                                                                            SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                                            SelectedLeaf::Matched { node, kind, presence } => {
                                                                                match kind {
                                                                                    SelectedNodeKind::Kind("double_quote") => {
                                                                                        match presence {
                                                                                            SelectedNodePresence::Present => {
                                                                                                NodeSlot::Present(DoubleQuoteNode(node))
                                                                                            }
                                                                                            SelectedNodePresence::Missing => {
                                                                                                NodeSlot::Missing(KindMissing(DoubleQuoteNode(node)))
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                                    }
                                                                                }
                                                                            }
                                                                        };
                                                                        Ok(Positioned::new(leading_extras, slot))
                                                                    }
                                                                }?;
                                                                let child_1 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    __selected.leaf_span(__raw)
                                                                }?;
                                                                let child_2 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    {
                                                                        let (leading_extras, leaf) = __selected
                                                                            .leaf_position(__unexpected)?;
                                                                        let slot = match leaf {
                                                                            SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                                            SelectedLeaf::Matched { node, kind, presence } => {
                                                                                match kind {
                                                                                    SelectedNodeKind::Kind("double_quote") => {
                                                                                        match presence {
                                                                                            SelectedNodePresence::Present => {
                                                                                                NodeSlot::Present(DoubleQuoteNode(node))
                                                                                            }
                                                                                            SelectedNodePresence::Missing => {
                                                                                                NodeSlot::Missing(KindMissing(DoubleQuoteNode(node)))
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                                    }
                                                                                }
                                                                            }
                                                                        };
                                                                        Ok(Positioned::new(leading_extras, slot))
                                                                    }
                                                                }?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(MediaFilenameDoubleQuoteChildren {
                                                                    child_0,
                                                                    child_1,
                                                                    child_2,
                                                                    trailing_extras: Vec::new(),
                                                                    unexpected: Vec::new(),
                                                                })
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        MediaFilenameChoice::RNTRNRNT(
                                                            ({
                                                                if !matches!(
                                                                    __selected.read() ? .decision, MatchDecision::Empty
                                                                ) {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                }
                                                                Ok::<_, ReconstructionFault>(LeafText(__raw))
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        MediaFilenameChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
