/// `media_filename`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_media_filename_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<MediaFilenameChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_media_filename(MediaFilenameNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

