/// Concrete alternatives of an already range-admitted single-node choice.
#[derive(Debug, Clone, Copy)]
pub enum OptionNameChoiceBoundView<'tree, 'source> {
    CA(SourceBound<'tree, 'source, CANode<'tree>>),
    NoAlign(SourceBound<'tree, 'source, NoAlignNode<'tree>>),
    GenericOptionName(SourceBound<'tree, 'source, GenericOptionNameNode<'tree>>),
}
impl<'tree, 'source> SourceBound<'tree, 'source, OptionNameChoice<'tree>> {
    /// Preserve the admitted range when selecting the same underlying node.
    #[must_use]
    pub fn view(self) -> OptionNameChoiceBoundView<'tree, 'source> {
        match self.node {
            OptionNameChoice::CA(node) => {
                OptionNameChoiceBoundView::CA(SourceBound::from_slice(node, self.source_slice()))
            }
            OptionNameChoice::NoAlign(node) => OptionNameChoiceBoundView::NoAlign(
                SourceBound::from_slice(node, self.source_slice()),
            ),
            OptionNameChoice::GenericOptionName(node) => {
                OptionNameChoiceBoundView::GenericOptionName(SourceBound::from_slice(
                    node,
                    self.source_slice(),
                ))
            }
        }
    }
}
/// A generated choice whose payload retains canonical source identity.
#[derive(Debug)]
pub enum OptionNameChoiceSourceView<'value, 'tree, 'source> {
    CA(SourceField<'value, 'tree, 'source, CANode<'tree>>),
    NoAlign(SourceField<'value, 'tree, 'source, NoAlignNode<'tree>>),
    GenericOptionName(SourceField<'value, 'tree, 'source, GenericOptionNameNode<'tree>>),
}
impl<'value, 'tree, 'source> SourceField<'value, 'tree, 'source, OptionNameChoice<'tree>> {
    /// Admit the canonical node represented by this generated choice.
    /// # Errors
    /// Rejects an unreadable canonical source range.
    pub fn read_raw(self) -> Result<SourceSlice<'tree, 'source>, SourceBindingError> {
        SourceSlice::from_canonical(self.value.raw_node(), self.source())
    }
    /// Select the producer's variant without reclassifying or detaching it.
    #[must_use]
    pub fn view(self) -> OptionNameChoiceSourceView<'value, 'tree, 'source> {
        match self.value {
            OptionNameChoice::CA(value) => OptionNameChoiceSourceView::CA(SourceField {
                value,
                parent: self.parent,
            }),
            OptionNameChoice::NoAlign(value) => OptionNameChoiceSourceView::NoAlign(SourceField {
                value,
                parent: self.parent,
            }),
            OptionNameChoice::GenericOptionName(value) => {
                OptionNameChoiceSourceView::GenericOptionName(SourceField {
                    value,
                    parent: self.parent,
                })
            }
        }
    }
}
impl<'tree> AsRawNode<'tree> for OptionNameChoice<'tree> {
    fn raw_node(&self) -> tree_sitter::Node<'tree> {
        match self {
            OptionNameChoice::CA(inner) => inner.raw_node(),
            OptionNameChoice::NoAlign(inner) => inner.raw_node(),
            OptionNameChoice::GenericOptionName(inner) => inner.raw_node(),
        }
    }
}
impl<'tree> FromNodeKind<'tree> for OptionNameChoice<'tree> {
    /** Classify a node into this choice's own alternatives.

    Returns `None` for a node of any other kind. That is a refusal,
    not a failure: the caller holds a node this choice does not
    describe, and saying so is the only true answer available.*/
    fn from_node(node: tree_sitter::Node<'tree>) -> Option<Self> {
        match node.kind() {
            "CA" => Some(OptionNameChoice::CA(CANode(node))),
            "NoAlign" => Some(OptionNameChoice::NoAlign(NoAlignNode(node))),
            "generic_option_name" => Some(OptionNameChoice::GenericOptionName(
                GenericOptionNameNode(node),
            )),
            _ => None,
        }
    }
}
