/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_pho_group<'tree>(
    node: PhoGroupNode<'tree>,
) -> Result<PhoGroupChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_473, &cont_of(&SHAPES_3)) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        PhoGroupChoice::PhoWords(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("pho_words") => PhoWordsNode(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        PhoGroupChoice::PhoBeginGroup(
                                                            ({
                                                                let MatchDecision::Sequence(__members) = __selected
                                                                    .read()?
                                                                    .decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                if __members.len() != 3usize {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                }
                                                                let mut __members = __members.into_iter();
                                                                let child_0 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    {
                                                                        let (leading_extras, leaf) = __selected
                                                                            .leaf_position(__unexpected)?;
                                                                        let slot = match leaf {
                                                                            SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                                            SelectedLeaf::Matched { node, kind, presence } => {
                                                                                match kind {
                                                                                    SelectedNodeKind::Kind("pho_begin_group") => {
                                                                                        match presence {
                                                                                            SelectedNodePresence::Present => {
                                                                                                NodeSlot::Present(PhoBeginGroupNode(node))
                                                                                            }
                                                                                            SelectedNodePresence::Missing => {
                                                                                                NodeSlot::Missing(KindMissing(PhoBeginGroupNode(node)))
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                                    }
                                                                                }
                                                                            }
                                                                        };
                                                                        Ok(Positioned::new(leading_extras, slot))
                                                                    }
                                                                }?;
                                                                let child_1 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    {
                                                                        let (leading_extras, leaf) = __selected
                                                                            .leaf_position(__unexpected)?;
                                                                        let slot = match leaf {
                                                                            SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                                            SelectedLeaf::Matched { node, kind, presence } => {
                                                                                match kind {
                                                                                    SelectedNodeKind::Kind("pho_grouped_content") => {
                                                                                        match presence {
                                                                                            SelectedNodePresence::Present => {
                                                                                                NodeSlot::Present(PhoGroupedContentNode(node))
                                                                                            }
                                                                                            SelectedNodePresence::Missing => {
                                                                                                NodeSlot::Missing(KindMissing(PhoGroupedContentNode(node)))
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                                    }
                                                                                }
                                                                            }
                                                                        };
                                                                        Ok(Positioned::new(leading_extras, slot))
                                                                    }
                                                                }?;
                                                                let child_2 = {
                                                                    let __selected = __selected
                                                                        .child(
                                                                            __members
                                                                                .next()
                                                                                .ok_or(ReconstructionFault::UnexpectedDecision)?,
                                                                        )?;
                                                                    {
                                                                        let (leading_extras, leaf) = __selected
                                                                            .leaf_position(__unexpected)?;
                                                                        let slot = match leaf {
                                                                            SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                                            SelectedLeaf::Matched { node, kind, presence } => {
                                                                                match kind {
                                                                                    SelectedNodeKind::Kind("pho_end_group") => {
                                                                                        match presence {
                                                                                            SelectedNodePresence::Present => {
                                                                                                NodeSlot::Present(PhoEndGroupNode(node))
                                                                                            }
                                                                                            SelectedNodePresence::Missing => {
                                                                                                NodeSlot::Missing(KindMissing(PhoEndGroupNode(node)))
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                                    }
                                                                                }
                                                                            }
                                                                        };
                                                                        Ok(Positioned::new(leading_extras, slot))
                                                                    }
                                                                }?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(PhoGroupPhoBeginGroupChildren {
                                                                    child_0,
                                                                    child_1,
                                                                    child_2,
                                                                    trailing_extras: Vec::new(),
                                                                    unexpected: Vec::new(),
                                                                })
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        PhoGroupChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, PhoGroupNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, PhoGroupChildren<'tree>>, ReconstructionFault> {
        Ok(SourceChildren {
            children: extract_pho_group(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_pho_group_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, PhoGroupChildren<'tree>>>, ReconstructionFault>
    {
        extract_pho_group_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `pho_group`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_pho_group_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<PhoGroupChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_pho_group(PhoGroupNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

