/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_postcode<'tree>(
    node: PostcodeNode<'tree>,
) -> Result<PostcodeChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        {
            let child_0 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_497, &cont_of(&SHAPES_6)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("[+") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(LBrackPlusNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(LBrackPlusNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_1 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_18, &cont_of(&SHAPES_7)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("space") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(SpaceNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(SpaceNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let code = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_20, &cont_of(&SHAPES_8)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("annotation_content") => {
                                        match presence {
                                            SelectedNodePresence::Present => {
                                                NodeSlot::Present(AnnotationContentNode(node))
                                            }
                                            SelectedNodePresence::Missing => NodeSlot::Missing(
                                                KindMissing(AnnotationContentNode(node)),
                                            ),
                                        }
                                    }
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_3 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_22, &cont_of(&SHAPES_3)) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("right_bracket") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(RightBracketNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(RightBracketNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            PostcodeChildren {
                child_0,
                child_1,
                code,
                child_3,
                trailing_extras,
                unexpected,
            }
        }
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, PostcodeNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, PostcodeChildren<'tree>>, ReconstructionFault> {
        Ok(SourceChildren {
            children: extract_postcode(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_postcode_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, PostcodeChildren<'tree>>>, ReconstructionFault>
    {
        extract_postcode_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `postcode`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_postcode_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<PostcodeChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_postcode(PostcodeNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

