#[derive(Debug, Clone)]
pub struct SeparatorChildren<'tree> {
    /// The rule's whole content, as a single position: the carrier
    /// convention (spec Section 5) mirroring `fold::slot_of`.
    pub content: Positioned<'tree, ChoiceSlot<'tree, SeparatorChoice<'tree>>>,
    /// Extras that trail the last child of this node (spec Section 5).
    pub trailing_extras: Vec<Extra<'tree>>,
    /// Children that filled no grammar position: the Unexpected sink
    /// (spec Section 7). Never dropped.
    pub unexpected: Vec<tree_sitter::Node<'tree>>,
}
/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_separator<'tree>(
    node: SeparatorNode<'tree>,
) -> Result<SeparatorChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_520, &cont_of(&SHAPES_3)) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        SeparatorChoice::NonColonSeparator(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("non_colon_separator") => {
                                                                            NonColonSeparatorNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        SeparatorChoice::Colon(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    at,
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let node = __selected.node_at(at)?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("colon") => ColonNode(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        SeparatorChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, SeparatorNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, SeparatorChildren<'tree>>, ReconstructionFault> {
        Ok(SourceChildren {
            children: extract_separator(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_separator_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, SeparatorChildren<'tree>>>, ReconstructionFault>
    {
        extract_separator_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `separator`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_separator_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<SeparatorChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_separator(SeparatorNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

