impl<'tree, 'source> SourceBound<'tree, 'source, ShorteningNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, ShorteningChildren<'tree>>, ReconstructionFault>
    {
        Ok(SourceChildren {
            children: extract_shortening(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_shortening_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ShorteningChildren<'tree>>>,
        ReconstructionFault,
    > {
        extract_shortening_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `shortening`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_shortening_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ShorteningChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_shortening(ShorteningNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

