impl<'tree, 'source> SourceBound<'tree, 'source, SourceFileNode<'tree>> {
    /// Extract immutable positional children with their source owner.
    /// # Errors
    /// Propagates a reconstruction producer fault without inventing a source diagnostic.
    pub fn extract(
        self,
    ) -> Result<SourceChildren<'tree, 'source, SourceFileChildren<'tree>>, ReconstructionFault>
    {
        Ok(SourceChildren {
            children: extract_source_file(self.node)?,
            parent: self.source_slice(),
        })
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_source_file_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, SourceFileChildren<'tree>>>,
        ReconstructionFault,
    > {
        extract_source_file_from_error_recovery(self.node).map(|children| {
            children.map(|children| SourceChildren {
                children,
                parent: self,
            })
        })
    }
}
/// `source_file`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_source_file_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<SourceFileChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_source_file(SourceFileNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

