fn extract_spa_dependent_tier_admitted<'tree, 'source>(
    parent: AdmittedParent<'tree, 'source>,
) -> Result<
    SourceChildren<'tree, 'source, AdmittedSpaDependentTierChildren<'tree>>,
    ReconstructionFault,
> {
    let __raw = parent.source.node;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new_admitted(&__children, parent.grammar);
    Ok(SourceChildren {
        children: {
            {
                let child_0 = {
                    let (mut leading_extras, __at) = __cur.take_leading_extras();
                    match __at.select_position(&SHAPE_558, &cont_of(&SHAPES_0)) {
                        PositionAdmission::Selected(selection) => {
                            let built = selection.consume_with(|__selected, __unexpected| {
                                let (leading_extras, leaf) =
                                    __selected.leaf_position(__unexpected)?;
                                let slot = match leaf {
                                    SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                    SelectedLeaf::Matched {
                                        node,
                                        kind,
                                        presence,
                                    } => match kind {
                                        SelectedNodeKind::Kind("spa_tier_prefix") => match presence
                                        {
                                            SelectedNodePresence::Present => {
                                                NodeSlot::Present(SpaTierPrefixNode(node))
                                            }
                                            SelectedNodePresence::Missing => NodeSlot::Missing(
                                                KindMissing(SpaTierPrefixNode(node)),
                                            ),
                                        },
                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                            return Err(ReconstructionFault::UnexpectedDecision);
                                        }
                                    },
                                };
                                Ok(Positioned::new(leading_extras, slot))
                            })?;
                            leading_extras.extend(built.leading_extras);
                            Positioned::new(leading_extras, built.slot)
                        }
                        PositionAdmission::Unmatched(__at) => {
                            __at.release();
                            Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                        }
                    }
                };
                let child_1 = {
                    let (mut leading_extras, __at) = __cur.take_leading_extras();
                    match __at.select_position(&SHAPE_1, &cont_of(&SHAPES_1)) {
                        PositionAdmission::Selected(selection) => {
                            let built = selection.consume_with(|__selected, __unexpected| {
                                let (leading_extras, leaf) =
                                    __selected.nonmissing_leaf_position(__unexpected)?;
                                let slot = match leaf {
                                    NonMissingSelectedLeaf::Error(node) => NodeSlot::Error(node),
                                    NonMissingSelectedLeaf::Matched { node, kind } => match kind {
                                        SelectedNodeKind::Kind("tier_sep") => {
                                            NodeSlot::Present(TierSepNode(node))
                                        }
                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                            return Err(ReconstructionFault::UnexpectedDecision);
                                        }
                                    },
                                };
                                Ok(Positioned::new(leading_extras, slot))
                            })?;
                            leading_extras.extend(built.leading_extras);
                            Positioned::new(leading_extras, built.slot)
                        }
                        PositionAdmission::Unmatched(__at) => {
                            __at.release();
                            Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                        }
                    }
                };
                let child_2 = {
                    let (mut leading_extras, __at) = __cur.take_leading_extras();
                    match __at.select_position(&SHAPE_4, &cont_of(&SHAPES_2)) {
                        PositionAdmission::Selected(selection) => {
                            let built = selection
                                .consume_with(|__selected, __unexpected| {
                                    let (mut leading_extras, selected) = __selected
                                        .optional_position()?;
                                    let slot = match selected {
                                        Some(__selected) => {
                                            let selected = ({
                                                let (leading_extras, leaf) = __selected
                                                    .nonmissing_leaf_position(__unexpected)?;
                                                let slot = match leaf {
                                                    NonMissingSelectedLeaf::Error(node) => NodeSlot::Error(node),
                                                    NonMissingSelectedLeaf::Matched { node, kind } => {
                                                        match kind {
                                                            SelectedNodeKind::Kind("text_with_bullets") => {
                                                                NodeSlot::Present(TextWithBulletsNode(node))
                                                            }
                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                            }
                                                        }
                                                    }
                                                };
                                                Ok(Positioned::new(leading_extras, slot))
                                            })?;
                                            leading_extras.extend(selected.leading_extras);
                                            Some(selected.slot)
                                        }
                                        None => None,
                                    };
                                    Ok(Positioned::new(leading_extras, slot))
                                })?;
                            leading_extras.extend(built.leading_extras);
                            Positioned::new(leading_extras, built.slot)
                        }
                        PositionAdmission::Unmatched(__at) => {
                            __at.release();
                            return Err(ReconstructionFault::UnexpectedDecision);
                        }
                    }
                };
                let child_3 = {
                    let (mut leading_extras, __at) = __cur.take_leading_extras();
                    match __at.select_position(&SHAPE_6, &cont_of(&SHAPES_3)) {
                        PositionAdmission::Selected(selection) => {
                            let built = selection.consume_with(|__selected, __unexpected| {
                                let (leading_extras, leaf) =
                                    __selected.leaf_position(__unexpected)?;
                                let slot = match leaf {
                                    SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                    SelectedLeaf::Matched {
                                        node,
                                        kind,
                                        presence,
                                    } => match kind {
                                        SelectedNodeKind::Kind("newline") => match presence {
                                            SelectedNodePresence::Present => {
                                                NodeSlot::Present(NewlineNode(node))
                                            }
                                            SelectedNodePresence::Missing => {
                                                NodeSlot::Missing(KindMissing(NewlineNode(node)))
                                            }
                                        },
                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                            return Err(ReconstructionFault::UnexpectedDecision);
                                        }
                                    },
                                };
                                Ok(Positioned::new(leading_extras, slot))
                            })?;
                            leading_extras.extend(built.leading_extras);
                            Positioned::new(leading_extras, built.slot)
                        }
                        PositionAdmission::Unmatched(__at) => {
                            __at.release();
                            Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                        }
                    }
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                AdmittedSpaDependentTierChildren {
                    child_0,
                    child_1,
                    child_2,
                    child_3,
                    trailing_extras,
                    unexpected,
                }
            }
        },
        parent: parent.source,
    })
}
impl<'tree, 'source> SourceBound<'tree, 'source, SpaDependentTierNode<'tree>> {
    /// Extract under the compiled grammar proof, preserving other recovery.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        SourceChildren<'tree, 'source, AdmittedSpaDependentTierChildren<'tree>>,
        ReconstructionFault,
    > {
        extract_spa_dependent_tier_admitted(
            grammar
                .bind(self.source_slice())
                .map_err(ReconstructionFault::GrammarBinding)?,
        )
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct ERROR children under the same admitted producer contract.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_spa_dependent_tier_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, AdmittedSpaDependentTierChildren<'tree>>>,
        ReconstructionFault,
    > {
        let parent = grammar
            .bind(self)
            .map_err(ReconstructionFault::GrammarBinding)?;
        if self.node.is_error() {
            extract_spa_dependent_tier_admitted(parent).map(Some)
        } else {
            Ok(None)
        }
    }
}

