/// Selected alternative with readable leaves and unchanged recovery.
#[derive(Debug)]
pub enum AdmittedStandaloneWordChild0ChoiceRangeAdmitted<'tree, 'source> {
    WordPrefix(<WordPrefixNode<'tree> as AdmitRanges<'tree, 'source>>::Admitted),
    Zero(<ZeroNode<'tree> as AdmitRanges<'tree, 'source>>::Admitted),
}
