impl<'tree, 'source> AdmitRanges<'tree, 'source> for AdmittedStandaloneWordChild0Choice<'tree> {
    type Admitted = AdmittedStandaloneWordChild0ChoiceRangeAdmitted<'tree, 'source>;
    fn admit_ranges_in(
        self,
        context: &mut RangeAdmission<'tree, 'source>,
    ) -> Result<Self::Admitted, SourceBindingError> {
        Ok(match self {
            Self::WordPrefix(value) => AdmittedStandaloneWordChild0ChoiceRangeAdmitted::WordPrefix(
                value.admit_ranges_in(context)?,
            ),
            Self::Zero(value) => AdmittedStandaloneWordChild0ChoiceRangeAdmitted::Zero(
                value.admit_ranges_in(context)?,
            ),
        })
    }
}
