impl<'tree, 'source> SourceBound<'tree, 'source, UtteranceNode<'tree>> {
    /// Extract under the compiled grammar proof, preserving other recovery.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<SourceChildren<'tree, 'source, AdmittedUtteranceChildren<'tree>>, ReconstructionFault>
    {
        extract_utterance_admitted(
            grammar
                .bind(self.source_slice())
                .map_err(ReconstructionFault::GrammarBinding)?,
        )
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct ERROR children under the same admitted producer contract.
    /// # Errors
    /// Propagates language-binding or reconstruction faults.
    pub fn extract_utterance_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, AdmittedUtteranceChildren<'tree>>>,
        ReconstructionFault,
    > {
        let parent = grammar
            .bind(self)
            .map_err(ReconstructionFault::GrammarBinding)?;
        if self.node.is_error() {
            extract_utterance_admitted(parent).map(Some)
        } else {
            Ok(None)
        }
    }
}

